<?php use yii\helpers\Html;$this->title='Пользователь '.$model->username;?><div class="card p-4"><h2><?= Html::encode($model->username) ?></h2><table class="table"><tr><th>ID</th><td><?= $model->id ?></td></tr><tr><th>UUID</th><td class="font-monospace"><?= Html::encode($model->uuid) ?></td></tr><tr><th>Email</th><td><?= Html::encode($model->email) ?></td></tr><tr><th>Статус</th><td><?= Html::encode($model->status) ?></td></tr><tr><th>Launcher accessToken</th><td><?= $model->accessToken?'SET':'NULL' ?></td></tr><tr><th>serverID</th><td><?= Html::encode($model->serverID ?: 'NULL') ?></td></tr></table><div class="d-flex gap-2 flex-wrap"><?php foreach(['active','pending','blocked'] as $st):?><?= Html::beginForm(['/user/status','id'=>$model->id,'status'=>$st],'post').Html::submitButton($st,['class'=>'btn btn-outline-light']).Html::endForm() ?><?php endforeach;?></div><hr><h4>Роль</h4><div class="d-flex gap-2"><?php foreach(['user','moderator','admin'] as $r):?><?= Html::beginForm(['/user/role','id'=>$model->id,'role'=>$r],'post').Html::submitButton($r,['class'=>'btn btn-outline-primary']).Html::endForm() ?><?php endforeach;?></div><hr><h4>Gravit permissions</h4><div class="mb-3"><?php foreach($launcherPermissions as $lp):?><span class="badge text-bg-secondary me-2"><?= Html::encode($lp->name) ?> <?= Html::beginForm(['/user/delete-launcher-permission','id'=>$model->id,'name'=>$lp->name],'post',['class'=>'d-inline']).Html::submitButton('×',['class'=>'btn btn-link btn-sm text-white p-0']).Html::endForm() ?></span><?php endforeach;?></div><?= Html::beginForm(['/user/add-launcher-permission','id'=>$model->id],'post',['class'=>'d-flex gap-2']) ?><input class="form-control" name="permission" placeholder="launchserver.profile.<uuid>.*"><button class="btn btn-outline-primary">Добавить</button><?= Html::endForm() ?></div>